    WHERE project_id = v.project_id AND id = v.record_id AND (status = 'active'))) OR (v.type = 'plan' AND EXISTS (SELECT 1 FROM plans
    WHERE project_id = v.project_id AND plan_key = v.record_id AND (content IS NOT NULL OR (blob_key IS NOT NULL AND EXISTS (
  SELECT 1 FROM processed_resources pr WHERE pr.project_id = plans.project_id AND pr.kind = 'plan'
    AND pr.resource_id = plans.plan_key AND pr.blob_key = plans.blob_key AND pr.classification = 'processed'))))))) f WHERE (f.project_id,f.type,f.record_id,f.model_key)=(embedding_passed_over.project_id,embedding_passed_over.type,embedding_passed_over.record_id,embedding_passed_over.model_key)); INSERT INTO embedding_passed_over(project_id,type,record_id,model_key,revision,reason,recorded_at,expires_at)
      SELECT project_id,type,record_id,model_key,revision,reason,recorded_at,CASE WHEN model_key='' THEN NULL ELSE recorded_at+86400000 END FROM (SELECT f.* FROM (SELECT project_id,type,record_id,model_key FROM embedding_source_failures WHERE OLD.kind='plan' AND project_id=OLD.project_id AND type='plan' AND record_id=OLD.resource_id) k JOIN embedding_source_failures f
    ON (f.project_id,f.type,f.record_id,f.model_key)=(k.project_id,k.type,k.record_id,k.model_key)
    JOIN embedding_versions v ON (v.project_id,v.type,v.record_id)=(f.project_id,f.type,f.record_id)
    WHERE f.revision=v.revision AND ((v.type = 'session' AND EXISTS (SELECT 1 FROM sessions
    WHERE project_id = v.project_id AND session_id = v.record_id AND (summary IS NOT NULL AND trim(summary) <> ''))) OR (v.type = 'spore' AND EXISTS (SELECT 1 FROM spores
    WHERE project_id = v.project_id AND id = v.record_id AND (status = 'active'))) OR (v.type = 'plan' AND EXISTS (SELECT 1 FROM plans
    WHERE project_id = v.project_id AND plan_key = v.record_id AND (content IS NOT NULL OR (blob_key IS NOT NULL AND EXISTS (
  SELECT 1 FROM processed_resources pr WHERE pr.project_id = plans.project_id AND pr.kind = 'plan'
    AND pr.resource_id = plans.plan_key AND pr.blob_key = plans.blob_key AND pr.classification = 'processed'))))))) WHERE true
      ON CONFLICT(project_id,type,record_id,model_key) DO UPDATE SET revision=excluded.revision,reason=excluded.reason,recorded_at=excluded.recorded_at,expires_at=excluded.expires_at
      WHERE (embedding_passed_over.revision,embedding_passed_over.reason,embedding_passed_over.recorded_at,embedding_passed_over.expires_at)
        IS NOT (excluded.revision,excluded.reason,excluded.recorded_at,excluded.expires_at); END;

CREATE TRIGGER IF NOT EXISTS passed_over_version_update AFTER UPDATE OF revision ON embedding_versions BEGIN DELETE FROM embedding_passed_over WHERE (project_id,type,record_id)=(NEW.project_id,NEW.type,NEW.record_id) AND revision<>NEW.revision; END;

CREATE TRIGGER IF NOT EXISTS passed_over_version_delete AFTER DELETE ON embedding_versions BEGIN DELETE FROM embedding_passed_over WHERE (project_id,type,record_id)=(OLD.project_id,OLD.type,OLD.record_id); END;

CREATE TRIGGER IF NOT EXISTS change_mark_runs_insert AFTER INSERT ON agent_runs BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='runs'; END;

CREATE TRIGGER IF NOT EXISTS change_mark_runs_delete AFTER DELETE ON agent_runs BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='runs'; END;

CREATE TRIGGER IF NOT EXISTS change_mark_runs_update AFTER UPDATE OF status,held_by,completed_at ON agent_runs WHEN OLD.status IS NOT NEW.status OR OLD.held_by IS NOT NEW.held_by OR OLD.completed_at IS NOT NEW.completed_at BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='runs'; END;

CREATE TRIGGER IF NOT EXISTS change_mark_plans_insert AFTER INSERT ON plans BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='plans'; END;

CREATE TRIGGER IF NOT EXISTS change_mark_plans_delete AFTER DELETE ON plans BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='plans'; END;

CREATE TRIGGER IF NOT EXISTS change_mark_plans_update AFTER UPDATE ON plans WHEN OLD.project_id IS NOT NEW.project_id OR OLD.plan_key IS NOT NEW.plan_key OR OLD.session_id IS NOT NEW.session_id OR OLD.event_id IS NOT NEW.event_id OR OLD.machine_id IS NOT NEW.machine_id OR OLD.title IS NOT NEW.title OR OLD.content IS NOT NEW.content OR OLD.blob_key IS NOT NEW.blob_key OR OLD.content_hash IS NOT NEW.content_hash OR OLD.status IS NOT NEW.status OR OLD.origin_path IS NOT NEW.origin_path OR OLD.created_at IS NOT NEW.created_at OR OLD.updated_at IS NOT NEW.updated_at OR OLD.token_id IS NOT NEW.token_id OR OLD.received_at IS NOT NEW.received_at OR OLD.prompt_id IS NOT NEW.prompt_id OR OLD.updated_by IS NOT NEW.updated_by OR OLD.source IS NOT NEW.source BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='plans'; END;

CREATE TRIGGER IF NOT EXISTS change_mark_curation_insert AFTER INSERT ON spore_curation_changes BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='curation'; END;

CREATE TRIGGER IF NOT EXISTS change_mark_curation_delete AFTER DELETE ON spore_curation_changes BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='curation'; END;

CREATE TRIGGER IF NOT EXISTS change_mark_curation_update AFTER UPDATE ON spore_curation_changes WHEN OLD.project_id IS NOT NEW.project_id OR OLD.revision IS NOT NEW.revision OR OLD.dirty IS NOT NEW.dirty OR OLD.pending_at IS NOT NEW.pending_at BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='curation'; END;

INSERT INTO projection_catchup(projection,phase,done) SELECT 'passed_over','failures',NOT EXISTS(SELECT 1 FROM embedding_source_failures);

INSERT OR REPLACE INTO schema_meta (key, value) VALUES ('version', '712');
